/*!
 * wega-music-eshop.js - ENDLESS add-on for the Wega's Challenge music pack.
 * The game loads it by itself when an ENDLESS run needs it (it is not in index.html): it registers a lazy
 * "eshop" track with WegaMusic, decoded only while it plays. The music changes every 10 floors
 * (Endless, then Endless 1-5); the shop between floors has its own theme.
 * THE SHOP (Endless shop theme) - supplied by the player. Loops with a crossfade from 137.2 s (where its reverb tail starts) back to the top.
 */
(function (global) {
  "use strict";
  var D = global.WEGA_MUSIC_DATA, W = global.WegaMusic;
  if (!D || !W) { if (global.console) console.warn("[wega-music-eshop.js] load wega-music.js first"); return; }
  D.eshop = {
    title: "THE SHOP (Endless shop theme)",
    credit: "supplied by the player",
    duration: 139.807,
    loopStart: 0.0,
    loopEnd: 137.2,
    xfade: 2.5,
    gain: 0.7,
    lazy: true,
    src: "data:audio/mpeg;base64,"
  };
  if (W.tracks.indexOf("eshop") < 0) W.tracks.push("eshop");
  if (W.onPack) W.onPack("eshop");
})(typeof window !== "undefined" ? window : globalThis);
